-- 024_tatva.sql — Tatva (tatva.gamekatta.com) on this database: the Daily leaderboard,
-- rooms with a Daily league, and live game nights. Run after 016_night_presence.sql,
-- then run 025_tatva_data.sql (generated by gamekatta/tools/tatva/gen-sql.mjs). Safe to re-run.
--
-- Players are Borderline's players: one profiles row and one username for all of GameKatta.
-- The sign-in is shared through a cookie on .gamekatta.com (gk-session.js in both repos).
-- Tatva keeps its own rooms (tatva_rooms ...), so Borderline's rooms never change.
-- Every table has RLS on and no policies: clients only reach them through the functions below.
-- Errors raised here are shown to the player as they are, so keep them short and friendly.
--
-- Days are Tatva numbers: #1 is 8 Oct 2026, and a new one starts at midnight IST.
-- A result is the list of moves, as tatva.js saves it: atomic numbers (as text) for darts,
-- and 'home' / 'teacher' / 'half' for lifelines. The rules are tatva.js's:
--   · 10 darts. Each lifeline uses one up, once each, only after 3 darts and with 2+ darts left.
--   · Darts are distinct, and the game ends on the answer.
-- Points are the rank. n = darts thrown + lifelines used:
--   Found in 1:   1000
--   Found in n:   (11 − n) × 100 + aim (0–99)        2 = 900–999 … 10 = 100–199
--   Not found:    aim of the best dart (0–99)
--   aim = 0.99 × closeness (tatva.js's 0–100 score): the average of the darts before the
--   bullseye, or the best dart when it wasn't found. Same shape as Borderline's points.

-- ============================================================
-- Elements, the Daily answers and the practice pool (rows come from 025_tatva_data.sql)
-- ============================================================
create table if not exists public.tatva_elements (
  z      int  primary key check (z between 1 and 118),
  symbol text not null unique,
  g      int  not null,   -- column on the table (the f-block counts as 3)
  p      int  not null,   -- period
  fam    text not null
);
create table if not exists public.tatva_answers (
  day_no int primary key check (day_no >= 1),
  z      int not null references public.tatva_elements
);
-- Elements that are never a Daily: game nights draw from these and past Dailies
create table if not exists public.tatva_practice (
  z int primary key references public.tatva_elements
);

-- One result per player per Tatva day, written only by tatva_submit_daily()
create table if not exists public.tatva_scores (
  day_no     int  not null,
  user_id    uuid not null references auth.users on delete cascade,
  won        boolean not null,
  darts      int  not null,
  lifelines  int  not null,
  used       int  not null,
  points     int  not null,
  moves      text[] not null,
  created_at timestamptz not null default now(),
  primary key (day_no, user_id)
);
create index if not exists tatva_scores_rank_idx on public.tatva_scores (day_no, points desc, lifelines, created_at);
create index if not exists tatva_scores_user_idx on public.tatva_scores (user_id, day_no);

-- ============================================================
-- Rooms and game nights (same shape as Borderline's, see 009/014/016)
-- ============================================================
create table if not exists public.tatva_rooms (
  id         uuid primary key default gen_random_uuid(),
  code       text not null unique check (code ~ '^[A-Z2-9]{6}$'),
  name       text not null check (char_length(btrim(name)) between 2 and 40),
  owner_id   uuid not null references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  closed_at  timestamptz
);
create table if not exists public.tatva_room_members (
  room_id   uuid not null references public.tatva_rooms on delete cascade,
  user_id   uuid not null references auth.users on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
create index if not exists tatva_room_members_user_idx on public.tatva_room_members (user_id);

create table if not exists public.tatva_nights (
  id               uuid primary key default gen_random_uuid(),
  room_id          uuid not null references public.tatva_rooms on delete cascade,
  host_id          uuid not null references auth.users on delete cascade,
  rounds           int  not null check (rounds between 1 and 10),
  round_seconds    int  not null check (round_seconds between 60 and 600),
  current_round    int  not null default 0,
  round_started_at timestamptz,
  status           text not null default 'lobby' check (status in ('lobby', 'playing', 'ended')),
  created_at       timestamptz not null default now(),
  ended_at         timestamptz
);
create index if not exists tatva_nights_room_idx on public.tatva_nights (room_id, created_at desc);

create table if not exists public.tatva_night_players (
  night_id  uuid not null references public.tatva_nights on delete cascade,
  user_id   uuid not null references auth.users on delete cascade,
  joined_at timestamptz not null default now(),
  seen_at   timestamptz not null default now(),
  left_at   timestamptz,
  primary key (night_id, user_id)
);
create table if not exists public.tatva_night_rounds (
  night_id uuid not null references public.tatva_nights on delete cascade,
  round    int  not null,
  z        int  not null references public.tatva_elements,
  primary key (night_id, round)
);
create table if not exists public.tatva_night_results (
  night_id     uuid not null references public.tatva_nights on delete cascade,
  round        int  not null,
  user_id      uuid not null references auth.users on delete cascade,
  found        boolean not null,
  used         int  not null,
  seconds      int  not null,
  points       int  not null,
  moves        text[] not null,
  submitted_at timestamptz not null default now(),
  primary key (night_id, round, user_id)
);

alter table public.tatva_elements      enable row level security;
alter table public.tatva_answers       enable row level security;
alter table public.tatva_practice      enable row level security;
alter table public.tatva_scores        enable row level security;
alter table public.tatva_rooms         enable row level security;
alter table public.tatva_room_members  enable row level security;
alter table public.tatva_nights        enable row level security;
alter table public.tatva_night_players enable row level security;
alter table public.tatva_night_rounds  enable row level security;
alter table public.tatva_night_results enable row level security;

-- ============================================================
-- Helpers
-- ============================================================
-- Today's Tatva number (IST)
create or replace function public._tatva_today()
returns int language sql stable set search_path = '' as $$
  select ((now() at time zone 'Asia/Kolkata')::date - date '2026-10-08') + 1;
$$;

-- tatva.js closeness(): where two elements sit on the table, their family, their atomic numbers
create or replace function public._tatva_closeness(a int, b int)
returns int language sql stable security definer set search_path = '' as $$
  select case when a = b then 100 else
    round(97 * (0.4 * (1 - abs(x.g - y.g) / 17.0) + 0.3 * (1 - abs(x.p - y.p) / 6.0)
              + 0.2 * (x.fam = y.fam)::int + 0.1 * (1 - abs(x.z - y.z) / 117.0)))::int end
  from public.tatva_elements x, public.tatva_elements y
  where x.z = a and y.z = b;
$$;

-- Checks a list of moves against the rules. p_finished: the game must have ended (found, or
-- out of darts); a game night round can also end on the clock.
create or replace function public._tatva_check(p_moves text[], p_answer int, p_finished boolean,
  out won boolean, out darts int[], out lifelines int, out used int)
language plpgsql immutable set search_path = '' as $$
declare m text; v_z int; v_life text[] := '{}';
begin
  won := false; darts := '{}';
  foreach m in array coalesce(p_moves, '{}'::text[]) loop
    if won then raise exception 'That game was already won'; end if;
    if m in ('home', 'teacher', 'half') then
      if m = any (v_life) then raise exception 'Each lifeline works once'; end if;
      if cardinality(darts) < 3 then raise exception 'Lifelines open after 3 darts'; end if;
      if 10 - cardinality(darts) - cardinality(v_life) < 2 then raise exception 'No lifelines on the last dart'; end if;
      v_life := v_life || m;
    elsif m ~ '^[0-9]{1,3}$' then
      v_z := m::int;
      if v_z not between 1 and 118 then raise exception 'That isn''t an element'; end if;
      if v_z = any (darts) then raise exception 'The same element twice'; end if;
      if cardinality(darts) + cardinality(v_life) >= 10 then raise exception 'Out of darts'; end if;
      darts := darts || v_z;
      won := v_z = p_answer;
    else
      raise exception 'That isn''t a move';
    end if;
  end loop;
  lifelines := cardinality(v_life);
  used := cardinality(darts) + lifelines;
  if p_finished and not won and used < 10 then raise exception 'That game isn''t finished'; end if;
end $$;

create or replace function public._tatva_points(p_darts int[], p_won boolean, p_used int, p_answer int)
returns int language plpgsql stable security definer set search_path = '' as $$
declare n int := cardinality(p_darts); v_aim numeric;
begin
  if n = 0 then return 0; end if;
  if p_won then
    if p_used = 1 then return 1000; end if;
    select avg(public._tatva_closeness(d, p_answer)) into v_aim from unnest(p_darts[1:n - 1]) d;
    return greatest(1, 11 - p_used) * 100 + floor(0.99 * coalesce(v_aim, 0))::int;
  end if;
  select max(public._tatva_closeness(d, p_answer)) into v_aim from unnest(p_darts) d;
  return floor(0.99 * coalesce(v_aim, 0))::int;
end $$;

create or replace function public._tatva_is_member(p_room uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tatva_room_members where room_id = p_room and user_id = auth.uid());
$$;

create or replace function public._tatva_can_manage(p_room uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.tatva_rooms
                 where id = p_room and (owner_id = auth.uid() or public._is_admin()));
$$;

-- Over when ended, abandoned for 3 hours, or nobody has looked at it for 2 minutes
create or replace function public._tatva_night_over(n public.tatva_nights)
returns boolean language sql stable set search_path = '' as $$
  select n.status = 'ended'
      or n.created_at < now() - interval '3 hours'
      or not exists (select 1 from public.tatva_night_players p
                     where p.night_id = n.id and p.left_at is null and p.seen_at > now() - interval '2 minutes');
$$;

-- Players in the night right now: not left, seen in the last 45 seconds
create or replace function public._tatva_night_present(p_night uuid)
returns int language sql stable set search_path = '' as $$
  select count(*)::int from public.tatva_night_players
  where night_id = p_night and left_at is null and seen_at > now() - interval '45 seconds';
$$;

-- ============================================================
-- The Daily
-- ============================================================
-- Today's or yesterday's Tatva only, so a late offline sync still counts.
-- Returns the stored result; sending the same day again returns the first one.
create or replace function public.tatva_submit_daily(p_day int, p_moves text[])
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_today int := public._tatva_today(); v_answer int; c record;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if p_day > v_today or p_day < v_today - 1 then raise exception 'Tatva #% is closed', p_day; end if;
  select z into v_answer from public.tatva_answers where day_no = p_day;
  if v_answer is null then raise exception 'No answer for Tatva #%', p_day; end if;
  select * into c from public._tatva_check(p_moves, v_answer, true);
  insert into public.tatva_scores (day_no, user_id, won, darts, lifelines, used, points, moves)
  values (p_day, auth.uid(), c.won, cardinality(c.darts), c.lifelines, c.used,
          public._tatva_points(c.darts, c.won, c.used, v_answer), p_moves)
  on conflict (day_no, user_id) do nothing;
  return (select jsonb_build_object('day', day_no, 'won', won, 'used', used, 'lifelines', lifelines, 'points', points)
          from public.tatva_scores where day_no = p_day and user_id = auth.uid());
end $$;

-- Top named players for a day, plus the caller's own row wherever it ranks.
-- Ties: fewer lifelines, then whoever finished first.
create or replace function public.tatva_leaderboard(p_day int, p_limit int default 50)
returns table (rank bigint, username text, won boolean, used int, lifelines int, points int, is_me boolean, players bigint)
language sql stable security definer set search_path = '' as $$
  with ranked as (
    select s.user_id, p.username, s.won, s.used, s.lifelines, s.points,
           row_number() over (order by s.points desc, s.lifelines, s.created_at) as rank,
           count(*) over () as players
    from public.tatva_scores s
    join public.profiles p on p.id = s.user_id
    where s.day_no = p_day and p.username is not null
  )
  select rank, username, won, used, lifelines, points, user_id = auth.uid(), players
  from ranked
  where rank <= least(greatest(p_limit, 1), 100) or user_id = auth.uid()
  order by rank;
$$;

-- ============================================================
-- Rooms. Creating one needs the 'rooms_create' switch (008_roles.sql: admins and
-- managers), joining needs a username. A player can be in 5 Tatva rooms (people
-- who can create rooms: no limit); a room holds 50.
-- ============================================================
create or replace function public.tatva_create_room(p_name text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_code text; v_id uuid; v_name text := btrim(coalesce(p_name, ''));
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not public.has_feature('rooms_create') then raise exception 'Only GameKatta hosts can make rooms for now'; end if;
  if public._my_username() is null then raise exception 'Pick a name first'; end if;
  if char_length(v_name) not between 2 and 40 then raise exception 'Room names are 2 to 40 characters'; end if;
  if (select count(*) from public.tatva_rooms where owner_id = auth.uid() and closed_at is null) >= 20 then
    raise exception 'You have 20 rooms open already';
  end if;
  loop
    v_code := public._room_code();
    exit when not exists (select 1 from public.tatva_rooms where code = v_code);
  end loop;
  insert into public.tatva_rooms (code, name, owner_id) values (v_code, v_name, auth.uid()) returning id into v_id;
  insert into public.tatva_room_members (room_id, user_id) values (v_id, auth.uid());
  return jsonb_build_object('id', v_id, 'code', v_code, 'name', v_name);
end $$;

-- What an invite link shows before joining (null when there's no such room)
create or replace function public.tatva_room_preview(p_code text)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', r.id, 'name', r.name, 'code', r.code,
    'members', (select count(*) from public.tatva_room_members m where m.room_id = r.id),
    'full', (select count(*) from public.tatva_room_members m where m.room_id = r.id) >= 50,
    'member', public._tatva_is_member(r.id))
  from public.tatva_rooms r
  where r.code = upper(btrim(p_code)) and r.closed_at is null;
$$;

create or replace function public.tatva_join_room(p_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r public.tatva_rooms;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  select * into r from public.tatva_rooms where code = upper(btrim(coalesce(p_code, '')));
  if r.id is null or r.closed_at is not null then raise exception 'No room with that code'; end if;
  if public._tatva_is_member(r.id) then return jsonb_build_object('id', r.id, 'name', r.name); end if;
  if public._my_username() is null then raise exception 'Pick a name first'; end if;
  if (select count(*) from public.tatva_room_members where room_id = r.id) >= 50 then raise exception 'That room is full'; end if;
  if not public.has_feature('rooms_create')
     and (select count(*) from public.tatva_room_members m join public.tatva_rooms x on x.id = m.room_id
          where m.user_id = auth.uid() and x.closed_at is null) >= 5 then
    raise exception 'You''re in 5 rooms already. Leave one first';
  end if;
  insert into public.tatva_room_members (room_id, user_id) values (r.id, auth.uid()) on conflict do nothing;
  return jsonb_build_object('id', r.id, 'name', r.name);
end $$;

create or replace function public.tatva_leave_room(p_room uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from public.tatva_rooms where id = p_room and owner_id = auth.uid()) then
    raise exception 'You made this room, so you can close it but not leave it';
  end if;
  delete from public.tatva_room_members where room_id = p_room and user_id = auth.uid();
end $$;

-- Closed rooms disappear for everyone; their history stays in the database
create or replace function public.tatva_close_room(p_room uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public._tatva_can_manage(p_room) then raise exception 'Only the room''s owner can close it'; end if;
  update public.tatva_rooms set closed_at = now() where id = p_room and closed_at is null;
  update public.tatva_nights set status = 'ended', ended_at = now() where room_id = p_room and status <> 'ended';
end $$;

-- New code; the old invite link stops working
create or replace function public.tatva_reset_room_code(p_room uuid)
returns text language plpgsql security definer set search_path = '' as $$
declare v_code text;
begin
  if not public._tatva_can_manage(p_room) then raise exception 'Only the room''s owner can do that'; end if;
  loop
    v_code := public._room_code();
    exit when not exists (select 1 from public.tatva_rooms where code = v_code);
  end loop;
  update public.tatva_rooms set code = v_code where id = p_room;
  return v_code;
end $$;

create or replace function public.tatva_remove_member(p_room uuid, p_username text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_uid uuid;
begin
  if not public._tatva_can_manage(p_room) then raise exception 'Only the room''s owner can do that'; end if;
  select p.id into v_uid from public.profiles p join public.tatva_room_members m on m.user_id = p.id
  where m.room_id = p_room and p.username = p_username;
  if v_uid is null then raise exception 'Not in this room'; end if;
  if exists (select 1 from public.tatva_rooms where id = p_room and owner_id = v_uid) then
    raise exception 'The owner stays';
  end if;
  delete from public.tatva_room_members where room_id = p_room and user_id = v_uid;
end $$;

-- The rooms list
create or replace function public.tatva_my_rooms()
returns jsonb language sql stable security definer set search_path = '' as $$
  with today as (select public._tatva_today() as d)
  select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', r.id, 'name', r.name, 'code', r.code,
      'members', (select count(*) from public.tatva_room_members m where m.room_id = r.id),
      'played_today', (select count(*) from public.tatva_room_members m join public.tatva_scores s
                         on s.user_id = m.user_id and s.day_no = (select d from today) where m.room_id = r.id),
      'my_rank_today', (select rk from (
          select s.user_id, row_number() over (order by s.points desc, s.lifelines, s.created_at) as rk
          from public.tatva_room_members m join public.tatva_scores s on s.user_id = m.user_id and s.day_no = (select d from today)
          where m.room_id = r.id) t where t.user_id = auth.uid()),
      'can_manage', r.owner_id = auth.uid() or public._is_admin(),
      'live_night', (select n.id from public.tatva_nights n
                     where n.room_id = r.id and not public._tatva_night_over(n) order by n.created_at desc limit 1)
    ) as x
    from public.tatva_rooms r join public.tatva_room_members me on me.room_id = r.id and me.user_id = auth.uid()
    where r.closed_at is null
  ) q;
$$;

-- Everything the room screen shows. p_period: 'today' | 'week' | 'all'
create or replace function public.tatva_room_view(p_room uuid, p_period text default 'today')
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare r public.tatva_rooms; v_today int := public._tatva_today(); v_from int; v_out jsonb;
begin
  select * into r from public.tatva_rooms where id = p_room and closed_at is null;
  if r.id is null or not (public._tatva_is_member(p_room) or public._is_admin()) then raise exception 'Room not found'; end if;
  v_from := case p_period when 'week' then v_today - 6 when 'all' then 1 else v_today end;

  with members as (
    select m.user_id, p.username, m.joined_at from public.tatva_room_members m
    join public.profiles p on p.id = m.user_id where m.room_id = p_room
  ),
  streak_days as (
    select s.user_id, s.day_no, s.day_no - (row_number() over (partition by s.user_id order by s.day_no))::int as grp
    from public.tatva_scores s where s.user_id in (select user_id from members)
  ),
  streaks as (
    select user_id, max(len) as streak from (
      select user_id, grp, count(*) as len, max(day_no) as last_day from streak_days group by user_id, grp
    ) t where last_day >= v_today - 1 group by user_id
  ),
  league as (
    select mb.username, mb.user_id = auth.uid() as is_me,
           count(s.day_no) as played, count(*) filter (where s.won) as wins,
           round(avg(s.used) filter (where s.won), 1) as avg_used,
           coalesce(sum(s.points), 0) as points,
           sum(s.lifelines) as lifelines, min(s.created_at) as first_at,
           bool_or(s.won) as won, min(s.used) as used
    from members mb join public.tatva_scores s on s.user_id = mb.user_id and s.day_no between v_from and v_today
    where mb.username is not null
    group by mb.user_id, mb.username
  ),
  nights as (
    select n.id, n.created_at from public.tatva_nights n
    where n.room_id = p_room and public._tatva_night_over(n)
      and exists (select 1 from public.tatva_night_results x where x.night_id = n.id)
  ),
  night_totals as (
    -- one winner per night: most points, then fastest overall, then first in
    select n.id as night_id, n.created_at, x.user_id, sum(x.points) as points,
           row_number() over (partition by n.id order by sum(x.points) desc, sum(x.seconds), min(x.submitted_at)) as place
    from nights n join public.tatva_night_results x on x.night_id = n.id
    group by n.id, n.created_at, x.user_id
  )
  select jsonb_build_object(
    'room', jsonb_build_object('id', r.id, 'name', r.name, 'code', r.code, 'created_at', r.created_at,
                               'can_manage', r.owner_id = auth.uid() or public._is_admin(),
                               'is_owner', r.owner_id = auth.uid()),
    'period', p_period,
    'day', v_today,
    'members', coalesce((select jsonb_agg(jsonb_build_object(
        'username', mb.username, 'is_owner', mb.user_id = r.owner_id, 'is_me', mb.user_id = auth.uid(),
        'streak', coalesce(st.streak, 0),
        'played_today', exists (select 1 from public.tatva_scores s where s.user_id = mb.user_id and s.day_no = v_today))
        order by mb.joined_at)
      from members mb left join streaks st on st.user_id = mb.user_id), '[]'::jsonb),
    'league', coalesce((select jsonb_agg(row_to_json(l)::jsonb order by l.rank) from (
        select row_number() over (order by points desc, lifelines, wins desc, first_at) as rank,
               username, is_me, played, wins, avg_used, points, won, used
        from league) l), '[]'::jsonb),
    'nights', coalesce((select jsonb_agg(jsonb_build_object(
        'id', t.night_id, 'date', t.created_at,
        'players', (select count(distinct user_id) from night_totals z where z.night_id = t.night_id),
        'winner', p.username, 'points', t.points) order by t.created_at desc)
      from (select * from night_totals where place = 1 order by created_at desc limit 10) t
      join public.profiles p on p.id = t.user_id), '[]'::jsonb),
    'live_night', (select jsonb_build_object('id', n.id, 'status', n.status) from public.tatva_nights n
                   where n.room_id = p_room and not public._tatva_night_over(n) order by n.created_at desc limit 1)
  ) into v_out;
  return v_out;
end $$;

-- ============================================================
-- Game nights: timed rounds where everyone hunts the same element. Any member can
-- start one and hosts it; a night that's on can only be replaced by its host or the
-- room's owner. Round 1 needs two players who are here. Rounds draw from the
-- practice elements and past Dailies, so a night never gives away a Daily to come.
-- ============================================================
create or replace function public.tatva_start_night(p_room uuid, p_rounds int default 5, p_seconds int default 180)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_live public.tatva_nights;
begin
  if auth.uid() is null then raise exception 'Not signed in'; end if;
  if not exists (select 1 from public.tatva_rooms where id = p_room and closed_at is null) then raise exception 'Room not found'; end if;
  if not (public._tatva_is_member(p_room) or public._is_admin()) then raise exception 'Join the room first'; end if;
  select * into v_live from public.tatva_nights n
  where n.room_id = p_room and not public._tatva_night_over(n) order by n.created_at desc limit 1;
  if v_live.id is not null then
    if not (v_live.host_id = auth.uid() or public._tatva_can_manage(p_room)) then raise exception 'A game night is already on'; end if;
    update public.tatva_nights set status = 'ended', ended_at = now() where room_id = p_room and status <> 'ended';
  end if;
  insert into public.tatva_nights (room_id, host_id, rounds, round_seconds)
  values (p_room, auth.uid(), least(greatest(coalesce(p_rounds, 5), 1), 10), least(greatest(coalesce(p_seconds, 180), 60), 600))
  returning id into v_id;
  insert into public.tatva_night_players (night_id, user_id) values (v_id, auth.uid());
  return v_id;
end $$;

-- Joining (or coming back after leaving)
create or replace function public.tatva_join_night(p_night uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare n public.tatva_nights;
begin
  select * into n from public.tatva_nights where id = p_night;
  if n.id is null or public._tatva_night_over(n) then raise exception 'That game night is over'; end if;
  if not public._tatva_is_member(n.room_id) then raise exception 'Join the room first'; end if;
  insert into public.tatva_night_players (night_id, user_id) values (p_night, auth.uid())
  on conflict (night_id, user_id) do update set left_at = null, seen_at = now();
end $$;

-- Leaving the night (not the room). In the lobby you're off the list; mid-game your
-- points stay. If the host leaves, the next player hosts; the last one out ends it.
create or replace function public.tatva_leave_night(p_night uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare n public.tatva_nights; v_next uuid;
begin
  select * into n from public.tatva_nights where id = p_night for update;
  if n.id is null then return; end if;
  if n.status = 'lobby' then
    delete from public.tatva_night_players where night_id = p_night and user_id = auth.uid();
  else
    update public.tatva_night_players set left_at = now() where night_id = p_night and user_id = auth.uid();
  end if;
  if n.status = 'ended' then return; end if;
  if n.host_id = auth.uid() then
    select user_id into v_next from public.tatva_night_players
    where night_id = p_night and left_at is null and user_id <> auth.uid()
    order by (seen_at > now() - interval '45 seconds') desc, joined_at limit 1;
    if v_next is not null then update public.tatva_nights set host_id = v_next where id = p_night; end if;
  end if;
  if not exists (select 1 from public.tatva_night_players where night_id = p_night and left_at is null) then
    update public.tatva_nights set status = 'ended', ended_at = now() where id = p_night;
  end if;
end $$;

create or replace function public.tatva_start_round(p_night uuid)
returns int language plpgsql security definer set search_path = '' as $$
declare n public.tatva_nights; v_z int;
begin
  select * into n from public.tatva_nights where id = p_night for update;
  if n.id is null or public._tatva_night_over(n) then raise exception 'That game night is over'; end if;
  if not (n.host_id = auth.uid() or public._tatva_can_manage(n.room_id)) then raise exception 'Only the host starts rounds'; end if;
  if n.current_round >= n.rounds then raise exception 'That was the last round'; end if;
  if n.current_round = 0 and public._tatva_night_present(p_night) < 2 then raise exception 'Need at least 2 players here'; end if;
  select c.z into v_z from (
    select z from public.tatva_practice
    union select z from public.tatva_answers where day_no < public._tatva_today()
  ) c
  where c.z not in (select z from public.tatva_night_rounds where night_id = p_night)
  order by random() limit 1;
  if v_z is null then raise exception 'Out of elements for tonight'; end if;
  insert into public.tatva_night_rounds (night_id, round, z) values (p_night, n.current_round + 1, v_z);
  update public.tatva_nights set current_round = n.current_round + 1, round_started_at = now(), status = 'playing'
  where id = p_night;
  return n.current_round + 1;
end $$;

-- A player's round. Found: 1000 − 100 per extra dart or lifeline (min 100) + up to 300 for
-- speed, timed by the server; not found: 0. Ten seconds of grace for a slow connection.
create or replace function public.tatva_submit_round(p_night uuid, p_round int, p_moves text[])
returns int language plpgsql security definer set search_path = '' as $$
declare n public.tatva_nights; v_z int; c record; v_secs int; v_points int;
begin
  select * into n from public.tatva_nights where id = p_night;
  if n.id is null or public._tatva_night_over(n) then raise exception 'That game night is over'; end if;
  if not exists (select 1 from public.tatva_night_players where night_id = p_night and user_id = auth.uid()) then
    raise exception 'You''re not in this game night';
  end if;
  if p_round <> n.current_round or n.status <> 'playing'
     or now() > n.round_started_at + make_interval(secs => n.round_seconds + 10) then
    raise exception 'That round is over';
  end if;
  select z into v_z from public.tatva_night_rounds where night_id = p_night and round = p_round;
  select * into c from public._tatva_check(p_moves, v_z, false);
  v_secs := least(greatest(extract(epoch from now() - n.round_started_at)::int, 0), n.round_seconds);
  v_points := case when c.won
                then greatest(100, 1000 - 100 * (c.used - 1)) + round(300 * (1 - v_secs::numeric / n.round_seconds))::int
                else 0 end;
  insert into public.tatva_night_results (night_id, round, user_id, found, used, seconds, points, moves)
  values (p_night, p_round, auth.uid(), c.won, c.used, v_secs, v_points, coalesce(p_moves, '{}'))
  on conflict do nothing;
  -- one result per player per round: sending it again gets the first one back
  return (select points from public.tatva_night_results where night_id = p_night and round = p_round and user_id = auth.uid());
end $$;

create or replace function public.tatva_end_night(p_night uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare n public.tatva_nights;
begin
  select * into n from public.tatva_nights where id = p_night;
  if n.id is null then raise exception 'Game night not found'; end if;
  if not (n.host_id = auth.uid() or public._tatva_can_manage(n.room_id)) then raise exception 'Only the host can end it'; end if;
  update public.tatva_nights set status = 'ended', ended_at = now() where id = p_night and status <> 'ended';
end $$;

-- Live state, polled every 2 seconds by players and the TV view; marks the caller as here.
-- phase: lobby | playing | between | final | ended. The round's element (z) goes only to
-- players of the night while the round is on, and to everyone once it's over. Anyone with
-- the night's id can watch the scoreboard (the TV view) but never sees the element early.
create or replace function public.tatva_night_state(p_night uuid)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare n public.tatva_nights; v_player boolean; v_round_over boolean; v_phase text; v_ends timestamptz;
        v_players int; v_submitted int;
begin
  update public.tatva_night_players set seen_at = now()
  where night_id = p_night and user_id = auth.uid() and left_at is null;
  select * into n from public.tatva_nights where id = p_night;
  if n.id is null then raise exception 'Game night not found'; end if;
  v_player := exists (select 1 from public.tatva_night_players where night_id = p_night and user_id = auth.uid() and left_at is null);
  v_ends   := n.round_started_at + make_interval(secs => n.round_seconds);
  v_players := public._tatva_night_present(p_night);
  select count(*) into v_submitted from public.tatva_night_results r
  join public.tatva_night_players p on p.night_id = r.night_id and p.user_id = r.user_id
  where r.night_id = p_night and r.round = n.current_round and p.left_at is null and p.seen_at > now() - interval '45 seconds';
  v_round_over := n.status = 'playing' and (now() > v_ends or v_submitted >= v_players);
  v_phase := case
    when public._tatva_night_over(n) then 'ended'
    when n.status = 'lobby' then 'lobby'
    when v_round_over and n.current_round >= n.rounds then 'final'
    when v_round_over then 'between'
    else 'playing' end;

  return jsonb_build_object(
    'id', n.id, 'room_id', n.room_id,
    'room_name', (select name from public.tatva_rooms where id = n.room_id),
    'phase', v_phase, 'round', n.current_round, 'rounds', n.rounds, 'round_seconds', n.round_seconds,
    'round_started_at', (extract(epoch from n.round_started_at) * 1000)::bigint,
    'server_now', (extract(epoch from now()) * 1000)::bigint,
    'is_host', n.host_id = auth.uid() or public._tatva_can_manage(n.room_id),
    'is_player', v_player,
    'is_member', public._tatva_is_member(n.room_id),
    'present', v_players,
    'z', case when v_phase = 'playing' and v_player
              then (select z from public.tatva_night_rounds where night_id = p_night and round = n.current_round) end,
    'last_z', case when v_phase in ('between', 'final', 'ended')
                   then (select z from public.tatva_night_rounds where night_id = p_night and round = n.current_round) end,
    'players', coalesce((select jsonb_agg(row_to_json(t)::jsonb order by t.points desc, t.username) from (
        select p.username, np.user_id = auth.uid() as is_me, np.user_id = n.host_id as is_host,
               np.left_at is not null as left,
               coalesce((select sum(x.points) from public.tatva_night_results x
                          where x.night_id = p_night and x.user_id = np.user_id), 0) as points,
               (select jsonb_build_object('found', x.found, 'used', x.used, 'seconds', x.seconds, 'points', x.points)
                  from public.tatva_night_results x
                 where x.night_id = p_night and x.round = n.current_round and x.user_id = np.user_id) as this_round
        from public.tatva_night_players np
        join public.profiles p on p.id = np.user_id
        where case when n.status = 'lobby'
                   then np.left_at is null and np.seen_at > now() - interval '45 seconds'
                   else np.left_at is null or exists (select 1 from public.tatva_night_results x
                                                      where x.night_id = p_night and x.user_id = np.user_id) end
      ) t), '[]'::jsonb)
  );
end $$;

-- ============================================================
-- Who can call what
-- ============================================================
do $$
declare f text;
begin
  foreach f in array array[
    'tatva_submit_daily(int, text[])', 'tatva_leaderboard(int, int)',
    'tatva_create_room(text)', 'tatva_room_preview(text)', 'tatva_join_room(text)', 'tatva_leave_room(uuid)',
    'tatva_close_room(uuid)', 'tatva_reset_room_code(uuid)', 'tatva_remove_member(uuid, text)',
    'tatva_my_rooms()', 'tatva_room_view(uuid, text)',
    'tatva_start_night(uuid, int, int)', 'tatva_join_night(uuid)', 'tatva_leave_night(uuid)',
    'tatva_start_round(uuid)', 'tatva_submit_round(uuid, int, text[])', 'tatva_end_night(uuid)',
    'tatva_night_state(uuid)']
  loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['_tatva_today()', '_tatva_closeness(int, int)', '_tatva_check(text[], int, boolean)',
                           '_tatva_points(int[], boolean, int, int)', '_tatva_is_member(uuid)', '_tatva_can_manage(uuid)',
                           '_tatva_night_over(public.tatva_nights)', '_tatva_night_present(uuid)']
  loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;
